parameters.jsCode:
// Um print por DASHBOARD, nao por destinatario: cinco pessoas recebendo o mesmo
// painel sao cinco linhas na fila e uma unica captura. Cada captura custa ~15s
// (load + espera de renderizacao dos visuais), entao deduplicar aqui e a
// diferenca entre o fluxo levar segundos ou minutos.
const vistos = new Map();

for (const item of $input.all()) {
  const linha = item.json;
  if (!vistos.has(linha.dashboard_id)) {
    vistos.set(linha.dashboard_id, {
      dashboard_id: linha.dashboard_id,
      url: linha.url,
      largura: linha.largura,
      altura: linha.altura,
      espera_ms: linha.espera_ms,
    });
  }
}

return [...vistos.values()].map((json) => ({ json }));

// O HTTP Request devolve so o binario do PNG -- o JSON de saida vem vazio. Sem
// este no, a saida do loop seria um monte de imagem sem identificacao e nao
// daria para casar cada print com as linhas da fila.
const origem = $('Loop dashboards').item.json;
const temImagem = Boolean($binary && $binary.data);

// O HTTP Request nomeia o arquivo pelo fim da URL ("capture", sem extensao), e
// o node do Outlook usa esse nome no anexo. Aqui ele vira "<dashboard>.png".
if (temImagem) {
  $binary.data.fileName = `${origem.dashboard_id}.png`;
  $binary.data.fileExtension = 'png';
  $binary.data.mimeType = 'image/png';
}

return {
  json: {
    dashboard_id: origem.dashboard_id,
    captura_ok: temImagem,
    // O no de captura esta com "continue on error": um dashboard fora do ar nao
    // pode derrubar o envio dos outros. Quando isso acontece o erro chega aqui
    // no json em vez do binario, e vira motivo registrado no envio_log.
    captura_erro: temImagem
      ? null
      : ($json.error?.message ?? 'capture_service nao devolveu imagem'),
  },
  binary: temImagem ? { data: $binary.data } : {},
};

// Junta a fila (uma linha por destinatario) com as capturas (uma por dashboard).
// A entrada aqui e a saida "done" do loop, ou seja, todas as capturas; a fila
// original vem por referencia ao no que a consultou.
const capturas = new Map();
for (const item of $input.all()) {
  capturas.set(item.json.dashboard_id, item);
}

const saida = [];
for (const linha of $('Fila de envio').all()) {
  const captura = capturas.get(linha.json.dashboard_id);
  const ok = Boolean(captura && captura.json.captura_ok);

  // Linhas sem captura seguem no fluxo de proposito, em vez de serem
  // descartadas: elas viram registro de 'erro' no envio_log, e e esse registro
  // que responde "por que o print nao chegou hoje?".
  saida.push({
    json: {
      ...linha.json,
      captura_ok: ok,
      detalhe: ok
        ? null
        : (captura?.json.captura_erro ?? 'dashboard nao foi capturado'),
    },
    binary: ok ? captura.binary : {},
  });
}

return saida;

// O Evolution API recebe a imagem como base64 dentro do JSON, entao o binario
// precisa virar texto antes do no de envio.
const entrada = $input.all();
const saida = [];

for (let i = 0; i < entrada.length; i++) {
  // getBinaryDataBuffer e o caminho correto: ler item.binary.data.data direto
  // so funciona quando o n8n guarda binario em memoria, e quebra quando esta
  // configurado para guardar em disco (N8N_DEFAULT_BINARY_DATA_MODE=filesystem).
  // O fallback cobre versoes do Code node que nao expoem helpers.
  const buffer = this.helpers?.getBinaryDataBuffer
    ? await this.helpers.getBinaryDataBuffer(i, 'data')
    : Buffer.from(entrada[i].binary.data.data, 'base64');

  saida.push({
    json: { ...entrada[i].json, png_base64: buffer.toString('base64') },
    pairedItem: { item: i },
  });
}

return saida;

// Os nos de envio substituem o JSON do item pela resposta da API, entao os
// dados do envio (qual distribuicao, que dia) vem por referencia ao no anterior.
const origem = $('Montar envios').item.json;

return {
  json: {
    distribuicao_id: origem.distribuicao_id,
    referencia: origem.referencia,
    status: 'enviado',
    detalhe: null,
  },
};

// Recebe tres tipos de item: falha de captura (vem direto do switch, com
// `detalhe` ja preenchido) e falha de envio no WhatsApp ou no email (vem da
// saida de erro do no, com `error`).
const origem = $('Montar envios').item.json;
// `error` chega como objeto ({ message }) no HTTP Request e como texto puro no
// node do Outlook. Lendo so `.message`, o erro do email se perdia e o registro
// virava um dump do item.
const erro = typeof $json.error === 'string' ? $json.error : $json.error?.message;
const motivo = erro ?? $json.detalhe ?? JSON.stringify($json).slice(0, 500);

return {
  json: {
    distribuicao_id: origem.distribuicao_id,
    referencia: origem.referencia,
    status: 'erro',
    // Truncado: o detalhe e para diagnostico humano, e resposta de API com
    // stack trace inteiro so atrapalha quem le a tabela.
    detalhe: String(motivo).slice(0, 1000),
  },
};

parameters.query:
INSERT INTO reporting.envio_log (distribuicao_id, referencia, status, detalhe)
VALUES ($1, $2::date, $3, $4)
ON CONFLICT DO NOTHING;
